ALTER TABLE memberships ADD COLUMN epoch TEXT NOT NULL DEFAULT '';
UPDATE memberships SET epoch=lower(hex(randomblob(16)));
CREATE TRIGGER membership_epoch_insert AFTER INSERT ON memberships BEGIN UPDATE memberships SET epoch=lower(hex(randomblob(16))) WHERE workspace_id=NEW.workspace_id AND user_id=NEW.user_id; END;
CREATE TRIGGER membership_epoch_role AFTER UPDATE OF role ON memberships WHEN NEW.role<>OLD.role BEGIN UPDATE memberships SET epoch=lower(hex(randomblob(16))) WHERE workspace_id=NEW.workspace_id AND user_id=NEW.user_id; END;
CREATE TABLE delivery_projects(project_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,version INTEGER NOT NULL,reviewers TEXT NOT NULL,baseline TEXT,plan_revision INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,UNIQUE(workspace_id,project_id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE delivery_tickets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,task_id TEXT NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,version INTEGER NOT NULL,phase TEXT NOT NULL,role_id TEXT NOT NULL,binding_id TEXT,packet_id TEXT,attempt_id TEXT,plan_revision INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(workspace_id,project_id,id),UNIQUE(workspace_id,task_id),FOREIGN KEY(workspace_id,project_id) REFERENCES delivery_projects(workspace_id,project_id),FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id),FOREIGN KEY(workspace_id,project_id,binding_id) REFERENCES agent_role_bindings(workspace_id,project_id,id));
CREATE TABLE agent_connections(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,profile_id TEXT NOT NULL,binding_id TEXT NOT NULL,binding_version INTEGER NOT NULL,operator_id TEXT NOT NULL REFERENCES users(id),membership_epoch TEXT NOT NULL,name TEXT NOT NULL,client_id TEXT UNIQUE,companion_client_id TEXT UNIQUE,state TEXT NOT NULL,initialized_at TEXT,lease_until TEXT,prepared TEXT,version INTEGER NOT NULL,created_at TEXT NOT NULL,revoked_at TEXT,UNIQUE(workspace_id,project_id,id),FOREIGN KEY(workspace_id,profile_id) REFERENCES agent_profiles(workspace_id,id),FOREIGN KEY(workspace_id,project_id,binding_id) REFERENCES agent_role_bindings(workspace_id,project_id,id));
CREATE TABLE delivery_packets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,ticket_id TEXT NOT NULL,binding_id TEXT NOT NULL,hash TEXT NOT NULL,payload TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,ticket_id) REFERENCES delivery_tickets(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,binding_id) REFERENCES agent_role_bindings(workspace_id,project_id,id));
CREATE TABLE delivery_attempts(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,ticket_id TEXT NOT NULL,packet_id TEXT NOT NULL,connection_id TEXT NOT NULL,profile_id TEXT NOT NULL,state TEXT NOT NULL,version INTEGER NOT NULL,grant_expires TEXT NOT NULL,lease_until TEXT,authorized_by TEXT NOT NULL REFERENCES users(id),authorized_at TEXT NOT NULL,started_at TEXT,ended_at TEXT,checkpoint TEXT,UNIQUE(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,ticket_id) REFERENCES delivery_tickets(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,packet_id) REFERENCES delivery_packets(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id,connection_id) REFERENCES agent_connections(workspace_id,project_id,id));
CREATE TABLE delivery_events(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,sequence INTEGER NOT NULL,ticket_id TEXT,actor_kind TEXT NOT NULL,actor_id TEXT NOT NULL,operator_id TEXT,action TEXT NOT NULL,reason TEXT NOT NULL,payload TEXT NOT NULL,request_id TEXT NOT NULL,input_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(workspace_id,project_id,sequence),UNIQUE(workspace_id,project_id,request_id),FOREIGN KEY(workspace_id,project_id) REFERENCES delivery_projects(workspace_id,project_id));
CREATE TABLE delivery_notices(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,event_id TEXT NOT NULL REFERENCES delivery_events(id),recipient_id TEXT NOT NULL REFERENCES users(id),ticket_id TEXT,sequence INTEGER NOT NULL,title TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT,UNIQUE(event_id,recipient_id),FOREIGN KEY(workspace_id,project_id) REFERENCES delivery_projects(workspace_id,project_id));
CREATE INDEX idx_delivery_tickets_page ON delivery_tickets(workspace_id,project_id,created_at,id);
CREATE INDEX idx_delivery_active_attempts ON delivery_attempts(workspace_id,profile_id,state,lease_until);
CREATE INDEX idx_delivery_notice_cursor ON delivery_notices(workspace_id,project_id,recipient_id,sequence);
